import React, { useState } from 'react';
import './styles.css';

export default function App() {
  const [step, setStep] = useState(1);
  const [name, setName] = useState('');
  const [age, setAge] = useState('');
  const [errors, setErrors] = useState({ name: '', age: '' });
  const [mode, setMode] = useState('');
  const [agreed, setAgreed] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  function handleNext() {
    const nextErrors = { name: '', age: '' };

    if (name.trim() === '') {
      nextErrors.name = '姓名不能为空';
    }

    const trimmedAge = age.trim();
    if (trimmedAge === '') {
      nextErrors.age = '年龄不能为空';
    } else {
      const ageNumber = Number(trimmedAge);
      if (!Number.isInteger(ageNumber)) {
        nextErrors.age = '年龄必须是整数';
      } else if (ageNumber < 18 || ageNumber > 60) {
        nextErrors.age = '年龄必须是 18 到 60 之间的整数';
      }
    }

    setErrors(nextErrors);

    if (nextErrors.name === '' && nextErrors.age === '') {
      setStep(2);
    }
  }

  function handleSubmit() {
    if (mode !== '' && agreed) {
      setSubmitted(true);
    }
  }

  if (step === 2) {
    return (
      <main className="wizard">
        <h1>报名向导</h1>
        <section data-testid="step2-placeholder" className="card">
          <h2>第 2 步：确认报名</h2>
          <div className="field">
            <span className="field-label">参加方式</span>
            <label className="option">
              <input
                type="radio"
                name="mode"
                value="online"
                checked={mode === 'online'}
                onChange={() => setMode('online')}
              />
              线上
            </label>
            <label className="option">
              <input
                type="radio"
                name="mode"
                value="offline"
                checked={mode === 'offline'}
                onChange={() => setMode('offline')}
              />
              线下
            </label>
          </div>
          <div className="field">
            <label className="option">
              <input
                type="checkbox"
                checked={agreed}
                onChange={(e) => setAgreed(e.target.checked)}
              />
              同意条款
            </label>
          </div>
          <button type="button" data-testid="submit-button" onClick={handleSubmit}>
            提交
          </button>
          {submitted && (
            <div data-testid="result-panel" className="result">
              <h3>报名成功</h3>
              <p>姓名：{name.trim()}</p>
              <p>年龄：{age.trim()}</p>
              <p>参加方式：{mode === 'online' ? '线上' : '线下'}</p>
            </div>
          )}
        </section>
      </main>
    );
  }

  return (
    <main className="wizard">
      <h1>报名向导</h1>
      <section className="card">
        <h2>第 1 步：填写基本信息</h2>
        <div className="field">
          <label htmlFor="name">姓名</label>
          <input
            id="name"
            data-testid="name-input"
            type="text"
            placeholder="请输入姓名"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          {errors.name && (
            <p className="error" data-testid="name-error">
              {errors.name}
            </p>
          )}
        </div>
        <div className="field">
          <label htmlFor="age">年龄</label>
          <input
            id="age"
            data-testid="age-input"
            type="text"
            placeholder="请输入年龄"
            value={age}
            onChange={(e) => setAge(e.target.value)}
          />
          {errors.age && (
            <p className="error" data-testid="age-error">
              {errors.age}
            </p>
          )}
        </div>
        <button type="button" data-testid="next-button" onClick={handleNext}>
          下一步
        </button>
      </section>
    </main>
  );
}

